entries[22736] = { ["name"] = "Andonisus, Der Seelenschlächter", ["text"] = "Stratholme\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 5 min (Realzeit)Waffenhand Schwert\n159 - 296 Schaden Tempo 2.80\n(81.25 Schaden pro Sekunde)\nHaltbarkeit 125 / 125\nBenötigt Stufe 60\nAnlegen: Erhöht die Nahkampf- und Distanzangriffskraft um 600.\n\"Die Klinge scheint aus dieser Existenzebene zu verblassen. Es sieht aus, als sei sie nicht von dieser Welt.\"" }
