entries[22852] = { ["name"] = "Drachenledertreter des Blutgardisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFüße Leder\n126 Rüstung\n+13 Stärke\n+6 Beweglichkeit\n+13 Ausdauer\n+6 Intelligenz\n+6 Willenskraft\nHaltbarkeit 50 / 50Klassen: Druide\nBenötigt Stufe 60\nAnlegen: Erhöht die Zaubermacht um 14.\n\nHaingewand des Feldherren (0/6)\nDrachenlederhandschutz des Blutgardisten\nDrachenledertreter des Blutgardisten\nDrachenlederbrustharnisch des Zornbringers\nDrachenledergamaschen des Zornbringers\nDrachenlederkopfschutz des Feldherren\nDrachenlederschultern des Feldherren\n(2) Set : Erhöht die Angriffskraft um 40.\n(4) Set : Erhöht Euer Bewegungstempo in Bären-, Katzen- oder Reisegestalt um 15%. Ist nur draußen aktiv.\n(6) Set : +20 Ausdauer." }
