entries[22900] = { ["name"] = "Rezept: Elixier der Tarnung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(305)\nBenutzen: Lehrt euch, wie man ein Elixier der Tarnung herstellt.\nElixier der Tarnung\nBenötigt Stufe 50\nBenutzen: Anwender kann 1 hour lang nicht aufgespürt werden. (3 Sek. Abklingzeit)\nBenötigt Zottelkappe , Teufelsgras , Magieerfüllte Phiole" }
entries[22901] = { ["name"] = "Rezept: Schleichtrank", ["text"] = "Benötigt Alchemie\n(315)\nBenutzen: Lehrt Euch die Herstellung eines Schleichtranks.\nSchleichtrank\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Verstohlenheit 1 min lang um einen großen Betrag. (1 Min Abklingzeit)\nBenötigt Zottelkappe (2), Teufelsgras , Magieerfüllte Phiole" }
entries[22902] = { ["name"] = "Rezept: Elixier der erheblichen Frostmacht", ["text"] = "Benötigt Alchemie\n(320)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Frostmacht.\nElixier der erheblichen Frostmacht\nBenötigt Stufe 50\nBenutzen: Erhöht die Frostzaubermacht 1 hour lang um 55. Kampfelixier. (3 Sek. Abklingzeit)\nBenötigt Wasserpartikel (2), Urflechte , Magieerfüllte Phiole" }
entries[22903] = { ["name"] = "Rezept: Trank der Wahnsinnsstärke", ["text"] = "Benötigt Alchemie\n(320)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der Wahnsinnsstärke.\nTrank der Wahnsinnsstärke\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Stärke um 120 und verringert Eure Verteidigungswertung um 75. Hält 15 sec lang an. (1 Min Abklingzeit)\nBenötigt Terozapfen (3), Magieerfüllte Phiole" }
entries[22904] = { ["name"] = "Rezept: Elixier des suchenden Auges", ["text"] = "Benötigt Alchemie\n(325)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers des suchenden Auges.\nElixier des suchenden Auges\nBenötigt Stufe 55\nBenutzen: Erhöht 10 min lang Eure Verstohlenheitsentdeckung. (3 Sek. Abklingzeit)\nBenötigt Zottelkappe (2), Terozapfen , Magieerfüllte Phiole" }
entries[22905] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(330)\nBenötigt Ehrenfeste\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nElixier der erheblichen Beweglichkeit\nBenötigt Stufe 55\nBenutzen: Erhöht 1 hour lang die Beweglichkeit um 30 und die kritische Trefferwertung um 12. Kampfelixier. (3 Sek. Abklingzeit)\nBenötigt Terozapfen , Teufelsgras (2), Magieerfüllte Phiole" }
entries[22906] = { ["name"] = "Rezept: Verschleierungstrank", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(335)\nBenötigt Sporeggar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Verschleierungstranks.\n\nVerschleierungstrank\nBenötigt Stufe 55\nBenutzen: Verschleiert Euch gegenüber nahen Feinden, sodass Ihr weniger bedrohlich erscheint. (1 Min Abklingzeit)\nBenötigt Zottelkappe (3), Netherblüte , Magieerfüllte Phiole" }
entries[22907] = { ["name"] = "Rezept: Erstklassiger Manatrank", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(340)\nBenutzen: Lehrt Euch die Herstellung eines erstklassigen Manatranks.\nErstklassiger Manatrank\nBenötigt Stufe 55\nBenutzen: Stellt 1800 to 3000 Mana wieder her. (1 Min Abklingzeit)\nBenötigt Traumwinde (2), Teufelsgras , Magieerfüllte Phiole" }
