entries[23755] = { ["name"] = "Zauberfoliant des Spaltens (Rang 3)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenötigt Stufe 68\nBenutzen: Lehrt Teufelswache 'Spalten' (Rang 3)." }
entries[23756] = { ["name"] = "Kräckas Jumboeintopf", ["text"] = "Benutzen: Stellt im Verlauf von 18 sec 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 2 Ausdauer und Willenskraft." }
entries[23757] = { ["name"] = "Raubkriecherfleisch", ["text"] = "Questgegenstand" }
entries[23758] = { ["name"] = "Zahnradbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Leder\n220 Rüstung\n<Zufällige Verzauberung>\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (340)" }
entries[23759] = { ["name"] = "Runenbesetzte Schrifttafel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 6" }
entries[23760] = { ["name"] = "Elunes Kelch", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein schimmerndes silbernes Gefäß, scheinbar ungetrübt vom anhaltenden Einfluss der Verderbnis.\"" }
entries[23761] = { ["name"] = "Energieverstärkungsbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Stoff\n100 Rüstung\n+46 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst (340)\nAnlegen: Erhöht die kritische Trefferwertung um 31.\nAnlegen: Erhöht die Zaubermacht um 36." }
entries[23762] = { ["name"] = "Ultraspektropische Enthüllungsbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Stoff\n124 Rüstung\n+36 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst (350)\nAnlegen: Erhöht die kritische Trefferwertung um 24.\nAnlegen: Erhöht die Trefferwertung um 24.\nAnlegen: Erhöht Eure Abhärtungswertung um 24.\nAnlegen: Erhöht die Tempowertung um 24.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen." }
entries[23763] = { ["name"] = "Extremsichtbrille", ["text"] = "Wird beim Anlegen gebunden\nKopf Leder\n232 Rüstung\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst (360)\nAnlegen: Erhöht die Trefferwertung um 23.\nAnlegen: Erhöht die Angriffskraft um 84.\nBenutzen: Erhöht 15 sec lang Eure Verstohlenheitsentdeckung. (2 Min Abklingzeit)" }
entries[23764] = { ["name"] = "Adamantitzielfernrohr", ["text"] = "Benötigt Stufe 55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 10.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[23765] = { ["name"] = "Khoriumzielfernrohr", ["text"] = "Benötigt Stufe 55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 12." }
entries[23766] = { ["name"] = "Geeichtes Eterniumzielfernrohr", ["text"] = "Benötigt Stufe 60\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht die kritische Trefferwertung dieser Waffe um 28.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[23767] = { ["name"] = "Krachbummroboter", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um einen robotischen Begleiter zu beschwören, der gegen andere Roboter kämpfen wird. (3 Min Abklingzeit)" }
